        raise NotFoundError(
            f"Schema {name} 不存在版本 {target_version}，也无报告以其为候选版本",
            details={"schema": name, "version": target_version},
        )

    # 起止相同：空步进，目标路径即入参路径。
    if baseline_version == target_version:
        return _result(name, baseline_version, target_version, path, path, [])

    graph = _ReportGraph.build(registry, reports, name)
    steps, final_path = graph.walk(baseline_version, path, target_version)
    return _result(
        name, baseline_version, target_version, path, final_path, steps
    )


# --------------------------------------------------------------- 请求校验
def _validate_request(
    name: Any, baseline_version: Any, target_version: Any, path: Any
) -> None:
    """请求级结构校验，失败统一抛 :class:`FieldTraceInvalid`。"""
    if not isinstance(name, str) or not name:
        raise FieldTraceInvalid(
            "Schema 名称必须是非空字符串", details={"reason": "invalid_schema"}
        )
    for label, version in (
        ("baseline_version", baseline_version),
        ("target_version", target_version),
    ):
        if not isinstance(version, str) or not version:
            raise FieldTraceInvalid(
                f"{label} 必须是非空字符串",
                details={"reason": "invalid_version", "field": label, "value": version},
            )
    if not isinstance(path, str):
        raise FieldTraceInvalid(
            "path 必须是 JSON Pointer 字符串",
            details={"reason": "invalid_path", "path": path},
        )
    try:
        ptr.parse(path)
    except ValueError as exc:
        raise FieldTraceInvalid(
            f"path 不是合法 JSON Pointer: {path!r}",
            details={"reason": "invalid_pointer", "path": path},
        ) from exc
    # 逻辑字段指针省略 properties 段、additionalProperties 写作 *、
    # 单 Schema items 写作 -；纯文本规整后发生变化说明传入的是文档指针。
    if ptr.normalize_field_pointer(path) != path:
        raise FieldTraceInvalid(
            f"path 不是逻辑字段指针（请省略 properties 等容器段）: {path!r}",
            details={"reason": "non_logical_pointer", "path": path},
        )


# --------------------------------------------------------------- 报告迁移图
class _ReportGraph:
    """同名 Schema 报告构成的相邻版本迁移图（不可变，只读构建）。"""

    def __init__(
        self,
        edges: dict[tuple[str, str], list[_ReportEdge]],
        candidate_fields: dict[tuple[str, str], dict[str, sf.Field] | None],
    ) -> None:
        self._edges = edges
        self._candidate_fields = candidate_fields

    @classmethod
    def build(
        cls, registry: Registry, reports: list[dict[str, Any]], name: str
    ) -> "_ReportGraph":
        edges: dict[tuple[str, str], list[_ReportEdge]] = {}
        candidate_fields: dict[tuple[str, str], dict[str, sf.Field] | None] = {}
        for report in reports:
            if report.get("schema") != name:
                continue
            old_ver = report.get("baseline_version")
            new_ver = report.get("candidate_version")
            if not isinstance(old_ver, str) or not isinstance(new_ver, str):
                # 无候选版本标签的报告无法形成版本间迁移边。
                continue
            key = (old_ver, new_ver)
            fields = candidate_fields.get(key, _UNSET)
            if fields is _UNSET:
                fields = cls._load_candidate_fields(registry, name, new_ver)
                candidate_fields[key] = fields
            edges.setdefault(key, []).append(
                _ReportEdge(
                    report["report_id"],
                    list(report.get("changes", [])),
                    list(report.get("renames", [])),
                    fields,
                )
            )
        for edge_list in edges.values():
            edge_list.sort(key=lambda e: e.report_id)
        return cls(edges, candidate_fields)

    @staticmethod
    def _load_candidate_fields(
        registry: Registry, name: str, version: str
    ) -> dict[str, sf.Field] | None:
        """候选版本已注册时返回其字段表；未注册（报告标签）返回 None。"""
        if not registry.has_schema(name, version):
            return None
        return sf.expand(registry.get_schema(name, version).document)

    def walk(
        self, start_version: str, start_path: str, target_version: str
    ) -> tuple[list[dict[str, Any]], str]:
        """BFS 求最短唯一血缘路线，返回 (步进列表, 目标路径)。

        每个状态为 ``(version, path)``；父指针在首次发现时确定，邻接状态
        按定位元组升序扩展，因此等长路线取确定性最小者。
        """
        start = (start_version, start_path)
        parent: dict[_State, tuple[_State | None, _StepEvidence | None]] = {
            start: (None, None)
        }
        queue: deque[_State] = deque([start])
        goal: _State | None = None
        while queue:
            version, path = queue.popleft()
            if version == target_version:
                goal = (version, path)
                break
            for nxt, evidence in self._neighbors(version, path):
                if nxt in parent:
                    continue
                parent[nxt] = ((version, path), evidence)
                queue.append(nxt)

        if goal is None:
            raise NotFoundError(
                f"字段 {start_path} 无从 {start_version} 到 {target_version} 的血缘路线"
                "（字段可能已被删除且无重命名传播）",
                details={
                    "reason": "lineage_not_found",
                    "path": start_path,
                    "from_version": start_version,
                    "to_version": target_version,
                },
            )

        steps: list[dict[str, Any]] = []
        cur = goal
        while parent[cur][0] is not None:
            prev, evidence = parent[cur]
            steps.append(
                {
                    "report_id": evidence.report_id,
                    "from_version": prev[0],
                    "to_version": cur[0],
                    "old_path": prev[1],
                    "new_path": cur[1],
                    "change_kind": evidence.change_kind,
                    "compatibility": evidence.compatibility,
                }
            )
            cur = prev
        steps.reverse()
        return steps, goal[1]

    def _neighbors(
        self, version: str, path: str
    ) -> list[tuple[_State, "_StepEvidence"]]:
        """展开某状态在全部相邻版本报告中的一致去向。

        同一对版本间的多份报告必须给出一致去向（终止也算一种去向），否则
        抛 :class:`FieldTraceAmbiguous`。不同相邻版本给出的去向按定位元组
        稳定排序。
        """
        out: list[tuple[_State, _StepEvidence]] = []
        for (old_ver, new_ver), edge_list in sorted(
            self._edges.items(), key=lambda kv: (kv[0][1], kv[0][0])
        ):
            if old_ver != version:
                continue
            signature = None
            chosen: _StepEvidence | None = None
            conflicts: list[dict[str, Any]] = []
            for edge in edge_list:
                outcome = edge.propagate(path)
                if signature is None:
                    signature = outcome.signature
                    chosen = outcome
                elif outcome.signature != signature:
                    conflicts.append(
                        {
                            "report_id": edge.report_id,
                            "paths": sorted(outcome.destinations),
                        }
                    )
            if conflicts:
                # 把首份（基准）报告也补进冲突明细，便于定位全部相关报告。
                conflicts.insert(
                    0,
                    {
                        "report_id": chosen.report_id if chosen else None,
                        "paths": sorted(signature_destinations(signature)),
                    },
                )
                raise FieldTraceAmbiguous(
                    f"版本 {old_ver} -> {new_ver} 的多份比较报告对字段 {path} "
                    "给出冲突去向，字段血缘不唯一",
                    details={
                        "reason": "conflicting_reports",
                        "from_version": old_ver,
                        "to_version": new_ver,
                        "path": path,
                        "conflicts": conflicts,
                    },
                )
            assert chosen is not None
            for dest_path in sorted(chosen.destinations):
                out.append(
                    (
                        (new_ver, dest_path),
                        _StepEvidence(
                            chosen.report_id,
                            chosen.change_kind,
                            chosen.compatibility,
                        ),
                    )
                )
        out.sort(key=lambda item: (ptr.parse(item[0][1]), item[0][1], item[0][0]))
        return out


_UNSET = object()
_State = tuple[str, str]


def signature_destinations(signature: Any) -> tuple[str, ...]:
    """从冲突比较签名中取出目标路径（终止签名为空）。"""
    return tuple(sorted(sig[1] for sig in signature)) or ()


class _StepEvidence:
    """一次步进的报告证据。"""

    __slots__ = ("report_id", "change_kind", "compatibility")

    def __init__(self, report_id: str, change_kind: str, compatibility: str) -> None:
        self.report_id = report_id
        self.change_kind = change_kind
        self.compatibility = compatibility


class _Outcome:
    """单份报告对某字段的传播结论。

    :ivar signature: 可比较的去向签名
        ``(((old_path, new_path), change_kind, compatibility), ...)``；
        字段终止为空 frozenset。多份报告签名不同即冲突。
    :ivar destinations: 去向新路径集合（空集表示终止）。
    """

    __slots__ = ("report_id", "signature", "destinations", "change_kind", "compatibility")

    def __init__(
        self,
        report_id: str,
        signature: frozenset,
        destinations: frozenset[str],
        change_kind: str,
        compatibility: str,
    ) -> None:
        self.report_id = report_id
        self.signature = signature
        self.destinations = destinations
        self.change_kind = change_kind
        self.compatibility = compatibility


class _ReportEdge:
    """一份报告形成的一条相邻版本迁移边。"""

    __slots__ = ("report_id", "_exact", "_renames", "_candidate_fields")

    def __init__(
        self,
        report_id: str,
        changes: list[dict[str, Any]],
        renames: list[dict[str, str]],
        candidate_fields: dict[str, sf.Field] | None,
    ) -> None:
        self.report_id = report_id
        # old_path -> 变更条目（同一 old_path 在一份报告中至多一条）。
        self._exact: dict[str, dict[str, Any]] = {}
        for change in changes:
            old_path = change.get("old_path")
            if isinstance(old_path, str):
                self._exact[old_path] = change
        # 重命名根（来自报告的 renames 声明，与 rename 条目同源），按路径
        # 段长度降序以便取最深的包含根。
        self._renames = sorted(
            (
                (r["from"], r["to"])
                for r in renames
                if isinstance(r, dict) and isinstance(r.get("from"), str)
                and isinstance(r.get("to"), str)
            ),
            key=lambda pair: (-len(ptr.parse(pair[0])), ptr.parse(pair[0]), pair[0]),
        )
        self._candidate_fields = candidate_fields

    def propagate(self, path: str) -> _Outcome:
        """计算字段经本报告的去向；同字段映向多个目标时抛歧义错误。"""
        change = self._exact.get(path)
        if change is not None:
            new_path = change.get("new_path")
            if new_path is None:
                return self._terminated()
            targets = {new_path}
            kind = change.get("change_kind", "modified")
            compat = change.get("compatibility", COMPATIBLE)
            return self._finish(path, targets, kind, compat)

        root = self._rename_root(path)
        if root is not None:
            src, dst = root
            suffix = ptr.parse(path)[len(ptr.parse(src)) :]
            new_path = ptr.format(list(ptr.parse(dst)) + list(suffix))
            return self._finish(path, {new_path}, "rename", "breaking")

        # 报告未涉及该字段：字段仍在候选版本即同路径保留（unchanged）。
        if self._exists_in_candidate(path):
            return self._finish(path, {path}, UNCHANGED, COMPATIBLE)
        return self._terminated()

    def _rename_root(self, path: str) -> tuple[str, str] | None:
        """返回最深的、包含该字段的重命名根。"""
        segs = ptr.parse(path)
        for src, dst in self._renames:
            root_segs = ptr.parse(src)
            if len(root_segs) < len(segs) and segs[: len(root_segs)] == root_segs:
                return src, dst
        return None

    def _exists_in_candidate(self, path: str) -> bool:
        fields = self._candidate_fields
        if fields is not None:
            return path in fields
        # 候选版本未注册时，删除必然在报告中留下 old_path == path 的
        # deleted 条目；没有该条目即字段仍在候选文档中。
        return path not in self._exact or self._exact[path].get("new_path") is not None

    def _finish(
        self,
        old_path: str,
        targets: set[str],
        change_kind: str,
        compatibility: str,
    ) -> _Outcome:
        if len(targets) > 1:
            raise FieldTraceAmbiguous(
                f"报告 {self.report_id} 中字段 {old_path} 的重命名目标不唯一",
                details={
                    "reason": "rename_target_not_unique",
                    "report_id": self.report_id,
                    "path": old_path,
                    "conflicts": [
                        {"report_id": self.report_id, "paths": sorted(targets)}
                    ],
                },
            )
        new_path = next(iter(targets))
        signature = frozenset(
            {((old_path, new_path), change_kind, compatibility)}
        )
        return _Outcome(
            self.report_id, signature, frozenset(targets), change_kind, compatibility
        )

    def _terminated(self) -> _Outcome:
        return _Outcome(self.report_id, _TERMINATED, frozenset(), "deleted", "breaking")


# --------------------------------------------------------------- 结果组装
def _result(
    schema: str,
    baseline_version: str,
    target_version: str,
    path: str,
    target_path: str,
    steps: list[dict[str, Any]],
) -> dict[str, Any]:
    counts: dict[str, int] = {}
    for step in steps:
        counts[step["change_kind"]] = counts.get(step["change_kind"], 0) + 1
    return {
        "schema": schema,
        "baseline_version": baseline_version,
        "target_version": target_version,
        "path": path,
        "target_path": target_path,
        "summary": {
            "steps": len(steps),
            "change_kinds": dict(sorted(counts.items())),
        },
        "steps": steps,
    }

